SELECT 
FROM model

    AND del_flag = '0'

        AND category = #{bo.category}


        AND model_name LIKE CONCAT('%', #{bo.modelName}, '%')


        AND provider_code LIKE CONCAT('%', #{bo.providerCode}, '%')


        AND model_describe = #{bo.modelDescribe}


        AND model_show = #{bo.modelShow}


        AND api_host = #{bo.apiHost}


        AND credential_key = #{bo.credentialKey}


        AND status = #{bo.status}


ORDER BY id ASC

SELECT id, model_name AS modelName, model_describe AS modelDescribe, remark
FROM model
WHERE id IN
#{id}
  AND category = #{category}
  AND status = #{status}
  AND model_show = #{modelShow}
  AND del_flag = '0'
ORDER BY provider_code ASC, model_name ASC

SELECT EXISTS(
    SELECT 1 FROM model WHERE provider_code IN
    #{providerCode}
)

SELECT EXISTS(
    SELECT 1 FROM model
    WHERE provider_code = #{providerCode}
      AND model_name = #{modelName}
      AND category = #{category}
      AND id != #{excludedId}
)
